package com.example.macroshizuku;
import android.content.Context;import org.json.*;import java.util.*;
public final class MacroStore {
 public static class Action{public String type;public float x1,y1,x2,y2;public long delay,duration;public Action(String t,float a,float b,float c,float d,long e,long f){type=t;x1=a;y1=b;x2=c;y2=d;delay=e;duration=f;}}
 public static class Macro{public String id,name;public float speed=1f;public int loops=1;public boolean floating=true;public int buttonWidth=0,buttonHeight=0,buttonAlpha=-1;public boolean buttonLocked=false;public boolean normalizedCoordinates=false;public List<Action> actions=new ArrayList<>();public Macro(String i,String n){id=i;name=n;}}
 private static final String PREF="macros",KEY="data";
 public static synchronized List<Macro> all(Context c){return fromJson(c.getSharedPreferences(PREF,0).getString(KEY,"[]"));}
 public static synchronized void saveAll(Context c,List<Macro> l){c.getSharedPreferences(PREF,0).edit().putString(KEY,toJson(l).toString()).apply();}
 public static synchronized Macro find(Context c,String id){
  if(id==null)return null;
  for(Macro m:all(c))if(id.equals(m.id))return m;
  return null;
 }
 public static void add(Context c,Macro m){List<Macro>x=all(c);x.add(m);saveAll(c,x);} public static void upsert(Context c,Macro m){List<Macro>x=all(c);boolean ok=false;for(int i=0;i<x.size();i++)if(x.get(i).id.equals(m.id)){x.set(i,m);ok=true;break;}if(!ok)x.add(m);saveAll(c,x);} public static void delete(Context c,String id){List<Macro>x=all(c);for(int i=x.size()-1;i>=0;i--)if(x.get(i).id.equals(id))x.remove(i);saveAll(c,x);}
 public static String exportJson(Context c){return toJson(all(c)).toString();} public static void importJson(Context c,String s){try{new JSONArray(s);}catch(JSONException e){throw new IllegalArgumentException("File backup không phải JSON macro hợp lệ",e);}saveAll(c,fromJson(s));}
 private static JSONArray toJson(List<Macro> l){JSONArray a=new JSONArray();try{for(Macro m:l){JSONObject o=new JSONObject();o.put("id",m.id);o.put("name",m.name);o.put("speed",m.speed);o.put("loops",m.loops);o.put("floating",m.floating);o.put("buttonWidth",m.buttonWidth);o.put("buttonHeight",m.buttonHeight);o.put("buttonAlpha",m.buttonAlpha);o.put("buttonLocked",m.buttonLocked);o.put("normalizedCoordinates",m.normalizedCoordinates);JSONArray aa=new JSONArray();for(Action x:m.actions){JSONObject z=new JSONObject();z.put("t",x.type);z.put("x1",x.x1);z.put("y1",x.y1);z.put("x2",x.x2);z.put("y2",x.y2);z.put("d",x.delay);z.put("du",x.duration);aa.put(z);}o.put("actions",aa);a.put(o);}}catch(Exception ignored){}return a;}
 private static List<Macro> fromJson(String s){List<Macro> out=new ArrayList<>();try{JSONArray a=new JSONArray(s);for(int i=0;i<a.length();i++){JSONObject m=a.getJSONObject(i);Macro x=new Macro(m.optString("id","m"+i),m.optString("name","Macro "+(i+1)));x.speed=(float)m.optDouble("speed",1);if(Float.isNaN(x.speed)||Float.isInfinite(x.speed))x.speed=1f;x.speed=Math.max(.25f,Math.min(10f,x.speed));x.loops=m.optInt("loops",1);if(x.loops<0)x.loops=0;x.floating=m.optBoolean("floating",true);x.buttonWidth=Math.max(0,Math.min(400,m.optInt("buttonWidth",0)));x.buttonHeight=Math.max(0,Math.min(400,m.optInt("buttonHeight",0)));int savedAlpha=m.optInt("buttonAlpha",-1);x.buttonAlpha=savedAlpha<0?-1:Math.max(0,Math.min(100,savedAlpha));x.buttonLocked=m.optBoolean("buttonLocked",false);x.normalizedCoordinates=m.optBoolean("normalizedCoordinates",false);JSONArray aa=m.optJSONArray("actions");if(aa!=null)for(int j=0;j<aa.length();j++){JSONObject o=aa.getJSONObject(j);String t=o.getString("t");if("move".equals(t))continue;x.actions.add(new Action(t,(float)o.getDouble("x1"),(float)o.getDouble("y1"),(float)o.getDouble("x2"),(float)o.getDouble("y2"),o.optLong("d"),o.optLong("du")));}out.add(x);}}catch(Exception ignored){}return out;}
}
